actions.script:
if (ec.user.userId && !ec.user.isInGroup('ADMIN')) throw new Error('Demo loading requires system administration')
const find = (productPriceId) => ec.entity.find('mantle.product.ProductPrice').condition('productPriceId', productPriceId).disableAuthz().one()
if (find('BOSS_PRICE_SALES') == null || find('BOSS_PRICE_NEXT') == null) {
    ec.logger.warn('The scheduled price demo needs BOSS_PRICE_SALES and BOSS_PRICE_NEXT; nothing moved')
    return
}
// the server's local day, as the demo data's fixed dates are read
const now = new Date(ec.user.timestampMillis(ec.user.nowTimestamp))
switchDate = String(new Date(now.getFullYear(), now.getMonth() + 2, 1).getTime())
const update = (fields) => ec.service.sync().name('update#mantle.product.ProductPrice').parameters(fields).disableAuthz().call()
update({productPriceId: 'BOSS_PRICE_SALES', thruDate: switchDate})
update({productPriceId: 'BOSS_PRICE_NEXT', fromDate: switchDate})
